T[1] = { { "Flüche und Krankheiten", "Etwas, das einen Fluch aufhebt oder eine Krankheit heilt, hilft sehr. Sonst ein leichter Kampf: Säubere den Raum, bevor du ihn angehst." } }
T[2] = { { "Der Beschwörer", "Töte zuerst den Beschwörer: Er ruft Verstärkung. Danach den Elementar." }, { "Feuer überall", "Flächenschaden auf die Gruppe, schlimmer, wenn die Gruppe viel im Nahkampf kämpft." } }
T[3] = { { "Quer durch den Raum geschleudert", "Er schleudert Spieler quer durch den Raum. Säubere die nächsten Gruppen und tanke ihn nahe am Tunnel, damit niemand in einer anderen Gruppe landet." } }
T[4] = { { "Furcht bei schwindendem Leben", "Wenn sein Leben sinkt, versetzt er die ganze Gruppe in Furcht. Plane etwas ein, um sie zu brechen, oder säubere vorher den Raum, damit niemand in andere Gegner rennt." }, { "Die verschlossenen Gewölbe", "Öffne nach dem Kampf die Gewölbe des Raums: etwa 24 Dwarven Heirlooms für Important Heirlooms und die Tafel von The Treaty of Understanding." } }
T[5] = { { "Feuernova", "Feuerschaden an allen in seiner Nähe, mehrmals pro Kampf. Als Heiler: Halte den Nahkampf bei vollem Leben." }, { "Aufwärtshaken", "Ein heftiger Schlag, der den Tank wegstößt." } }
T[6] = { { "Feuerbrand", "Verbrennt einen Spieler, dann alle paar Sekunden Feuerschaden für 21 Sekunden. Unterbrich den Zauber oder bann das Brennen." }, { "Fluch der Schwäche", "Verringert den körperlichen Schaden eines Spielers für 30 Sekunden. Ein Magier oder Druide kann ihn entfernen." } }
T[7] = { { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten steht." } }
T[8] = { { "Gift", "Seine Schläge vergiften: Naturschaden über Zeit. Heile das Gift, wenn du kannst." }, { "Heimtückischer Angriff", "Zusätzlicher Schaden auf den Tank alle 5 bis 15 Sekunden." } }
T[9] = { { "Die Spinnen im Hof", "Nichts Besonderes am Boss selbst. Säubere zuerst die anderen Spinnen im Hof, sonst schließen sie sich dem Kampf an." } }
T[10] = { note = "Säubere den Hof, klick auf die Statue und halte während der Wellen durch: Sie kommt danach.", { "Frostnova", "Frostschaden auf die ganze Gruppe. Wenn du heilst, spar Mana für alle Wellen." } }
T[11] = { { "In die Luft geschleudert", "Schleudert den Tank in die Luft und betäubt ihn 5 Sekunden lang. Achte als Schadensverursacher auf die Bedrohung: Der Tank hält ihn nur etwa den halben Kampf." }, { "Eine Patrouille", "Säubere seinen Raum, bevor du ihn angehst: Eine Patrouille kommt dort vorbei. Sein Kopf wird für die Quests Abominable Creatures und Unending Torment aufgesammelt." } }
T[12] = { { "Flammenschock", "Sein Hauptzauber. Er kann unterbrochen und betäubt werden: Koordiniere Unterbrechungen und Betäubungen mit der Gruppe." }, { "Viele Lebenspunkte", "Der längste Kampf des Dungeons. Unterbrich bis zum Schluss weiter." } }
T[13] = { note = "Säubere das Haus und die Statue, klick auf den Kamin und halte während der Wellen durch. Er kommt nach dem letzten Fleischgolem.", { "Gift", "Vergiftet sein Ziel. Behalte die Lebensbalken im Auge." }, { "Kräftige Schläge", "Er haut hart zu: Halte den Tank am Leben. Plane Manatränke für die Wellen vor ihm ein." } }
T[14] = { { "Zurückstoßen", "Er stößt zurück: Säubere zuerst die Gruppen um ihn herum, sonst landest du in einer davon." }, { "Antimagieschild", "Schützt sich eine Weile vor Zaubern." }, { "Kräftige Schläge", "Er haut hart zu: Halte den Tank bei vollem Leben." } }
T[15] = { { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." }, { "Heilende Berührung", "Heilt sich oder einen Verbündeten (3 Sekunden Zauberzeit). Unterbrich ihn." }, { "Cobrahns Schlangengestalt", "Bei 30 % Leben verwandelt er sich in eine Schlange: langsamere, aber schwerere Schläge, und er beginnt, Spieler einzuschläfern." } }
T[16] = { { "Heilende Berührung", "Heilt sich oder einen Verbündeten. Unterbrich sie." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf. Schaden weckt ihn, und Magie bannen entfernt ihn." }, { "Dornenaura", "Naturschaden an jedem, der sie im Nahkampf schlägt." } }
T[17] = { { "Panzerschild", "12 Sekunden lang erleidet er 60 % weniger Schaden und greift langsamer, aber härter an." } }
T[18] = { { "Donnerschlag", "Naturschaden an allen in seiner Nähe, dann 10 Sekunden lang verlangsamte Angriffe und Bewegungen." }, { "Heilende Berührung", "Heilt sich oder einen Verbündeten. Unterbrich ihn." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf." } }
T[19] = { { "Kettenblitz", "Ein Blitz, der auf einen zweiten Spieler überspringt. Unterbrich ihn." } }
T[20] = { { "Heilende Berührung", "Eine langsame Heilung (3,5 Sekunden) auf sich oder einen Verbündeten. Unterbrich ihn." }, { "Schlaf", "Versetzt einen Spieler bis zu 20 Sekunden lang in Schlaf." }, { "Blitzschlag", "Er hält Abstand, um ihn zu wirken. Unterbrich ihn." } }
T[21] = { { "Packende Ranken", "Wenn sein Ziel nah ist, wirft er alle in seiner Nähe um und hält sie 10 Sekunden lang fest. Bleib auf Abstand, wenn du weit weg bist." } }
T[22] = { note = "Töte Lady Anacondra, Lord Cobrahn, Lord Pythas und Lord Serpentis, sprich dann am Eingang mit Naralex' Schüler und eskortiere ihn zu Naralex. Beschütze ihn während des Rituals: Mutanus kommt am Ende.", { "Donnerknall", "Naturschaden an allen in seiner Nähe und eine Betäubung von 2,5 Sekunden." }, { "Naralex' Alptraum", "Versetzt einen Spieler bis zu 15 Sekunden lang in Schlaf." }, { "Schrecken", "Lässt einen Spieler 4 Sekunden lang in Furcht fliehen." } }
T[23] = { { "Rhahk'Zors Schlag", "Schlägt den Tank hart und betäubt ihn 3 Sekunden lang." } }
T[24] = { { "Rüstung durchbohren", "Verringert die Rüstung des Tanks 20 Sekunden lang um 75 %." }, { "Flieht um Hilfe", "Bei 15 % Leben flieht er, um Hilfe zu holen. Erledige ihn, bevor er sich entfernt." } }
