T[30] = { { "Zweimal zuschlagen", "Gelegentlich zwei Zusatzangriffe: harte Treffer auf den Tank." }, { "VanCleefs Verbündete", "Bei der Hälfte seines Lebens ruft er zwei Defias-Schurken." } }
