T[36] = { { "Heiliges Licht", "Heilt sich oder einen Verbündeten (2,5 Sekunden Zauberzeit). Unterbrich ihn." }, { "Gottesschild", "Macht ihn 10 Sekunden lang immun gegen allen Schaden und alle Zauber." }, { "Hammer der Gerechtigkeit", "Betäubt einen Spieler für 4 Sekunden." } }
