T[38] = { { "Spalten", "Trifft sein Ziel und den Spieler, der ihm am nächsten steht." }, { "Kniesehne", "Verlangsamt die Bewegung seines Ziels für 10 Sekunden." } }
T[39] = { note = "Sie kommen zu viert, nachdem Fenrus der Verschlinger gestorben ist: Arugal erscheint kurz und ruft sie.", { "Dunkles Opfer", "Heilt einen anderen Leerwandler. Tötet sie nacheinander." } }
T[40] = { { "Giftiger Speichel", "Naturschaden alle 6 Sekunden und Manaentzug, 2 Minuten lang. Heile das Gift." } }
