T[43] = { { "Zertrampeln", "Trifft alle, die in seiner Nähe stehen." } }
T[44] = { { "Gegabelter Blitz", "Naturschaden in einem Kegel vor ihr (2 Sekunden Zauberzeit). Bleib aus dem Kegel." }, { "Frostnova", "Friert alle in ihrer Nähe bis zu 8 Sekunden lang fest." }, { "Verlangsamen", "Verlangsamt Bewegung und Angriffe eines Spielers für 10 Sekunden." } }
T[45] = { { "Netz", "Hält einen Spieler 10 Sekunden lang an Ort und Stelle fest." } }
T[46] = { note = "Klick auf den Stein der Brasse im Wasser: Er taucht daraus auf.", { "Frostblitz", "Er hält Abstand, um ihn zu wirken: Frostschaden und Verlangsamung." }, { "Frostnova", "Hält alle in seiner Nähe bis zu 8 Sekunden lang fest." } }
T[47] = { { "Schlaf", "Versetzt alle in seiner Nähe bis zu 10 Sekunden lang in Schlaf. Schaden weckt einen Schläfer auf." }, { "Gedankenschlag", "Schattenschaden auf einen Spieler (1,5 Sekunden Zauberzeit)." } }
