T[56] = { { "Netz", "Hält alle in seiner Nähe 10 Sekunden lang fest." }, { "Verlangsamen", "Verlangsamt Angriffe und Bewegung eines Spielers für 10 Sekunden und kann ihn betäuben." }, { "Mechanische Schabe beschwören", "Ruft mechanische Schaben. Sein Update tötet sie und heilt ihn." } }
T[57] = { note = "Sprich mit Sprengmeisterin Emi Shortfuse und beschütze sie, während sie die beiden Höhleneingänge sprengt. Troggs kommen in Wellen, dann erscheint Grubbis mit Chomper." }
T[58] = { { "Megavolt", "Naturschaden in einem Kegel vor ihm (2 Sekunden Zauberzeit). Nur der Tank steht davor." }, { "Kettenblitzschlag", "Ein Blitz, der auf Spieler in der Nähe überspringt (2,5 Sekunden Zauberzeit). Unterbrich ihn." } }
