T[61] = { { "Laufende Bomben", "Er entzündet nacheinander die Gnomenköpfe rund um den Raum, und jeder lässt laufende Bomben los, die beim Erreichen eines Spielers explodieren. Der Knopf neben einem Kopf schaltet ihn aus. Unter der Hälfte seines Lebens entzündet er sie schneller." }, { "Wegstoßen", "Stößt den Tank weg. Unter der Hälfte seines Lebens trifft es alle um ihn herum." } }
